 dict(id='conj', en='Conjunctions & linking words', th='คำเชื่อม (conjunction) และคำเชื่อมความ',
  intro='คำเชื่อมต่อคำหรือประโยคเข้าด้วยกัน และบอกความสัมพันธ์: เพิ่ม ขัดแย้ง เหตุ ผล หรือเวลา',
  r=[['เชื่อมของที่เท่ากัน (FANBOYS)', 'for, and, nor, but, or, yet, so', [['The test passed, <b>but</b> the report is late.', 'ทดสอบผ่านแล้ว แต่รายงานช้า']]],
     ['เชื่อมประโยคหลักกับประโยครอง', 'because, although, while, when, if, unless, until, since + ประโยค (มีประธาน + กริยา)', [['<b>Although</b> it was expensive, we bought it.', 'แม้จะแพง เราก็ซื้อ']]],
     ['because กับ because of', 'because + ประโยค / because of (และ due to) + คำนาม', [['<b>because</b> the road was closed / <b>because of</b> the road closure', 'เพราะถนนปิด']]],
     ['คำเชื่อมความระหว่างประโยค', 'however, therefore, moreover, in addition, as a result เป็น adverb วางต้นประโยคตามด้วย comma', [['The cost rose. <b>However</b>, sales also increased.', 'ต้นทุนสูงขึ้น อย่างไรก็ตาม ยอดขายก็เพิ่มขึ้นด้วย']]]],
  q=[['We stopped the line _____ the sensor was broken.', ['because', 'because of', 'although', 'so'], 'ตามด้วยประโยค (the sensor was broken) ใช้ because'],
     ['The flight was delayed _____ the storm.', ['because of', 'because', 'although', 'so that'], 'ตามด้วยคำนาม (the storm) ใช้ because of'],
     ['_____ the price is high, the quality is excellent.', ['Although', 'Because', 'So', 'Unless'], 'สองความที่ขัดกัน ใช้ Although'],
     ['The supplier was late. _____, we missed the deadline.', ['As a result', 'However', 'Although', 'Unless'], 'ผลที่ตามมา ใช้ As a result'],
     ['The new design is lighter _____ cheaper.', ['and', 'but', 'or', 'so'], 'เพิ่มข้อดีสองอย่างที่ไปทางเดียวกัน ใช้ and'],
     ['Do not open the cover _____ the power is off.', ['unless', 'because', 'and', 'so'], 'unless = ถ้าไม่ (ห้ามเปิด ถ้าไฟยังไม่ปิด)'],
     ['Sales increased. _____, profits fell.', ['However', 'Therefore', 'Moreover', 'Because'], 'สองประโยคขัดกัน ใช้ However + comma'],
     ['Please wait here _____ the manager arrives.', ['until', 'unless', 'although', 'because of'], 'until = จนกระทั่ง']],
  rich=dict(
   hook='คำเชื่อมคือ "ป้ายจราจร" ของประโยค บอกผู้อ่านว่าความต่อไปจะไปทางเดิม (<b>and, moreover</b>) เลี้ยวกลับ (<b>but, however</b>) หรือเป็นผล (<b>so, therefore</b>) อ่านคำเชื่อมก่อน จะเดาความประโยคถัดไปได้',
   vis=[('table', ['ความหมาย', 'เชื่อมในประโยค', 'ต้นประโยคใหม่ (+ ,)'], [['เพิ่ม', 'and', 'Moreover, / In addition,'], ['ขัดแย้ง', 'but / although', 'However, / Nevertheless,'], ['เหตุ', 'because / since', '-'],
                                                                     ['ผล', 'so', 'Therefore, / As a result,'], ['เงื่อนไข', 'if / unless', '-'], ['เวลา', 'when / while / until', 'Then, / After that,']], 'เลือกคำเชื่อมจากความหมายก่อน แล้วดูตำแหน่ง')],
   f=[('เหตุ', 'because + ประโยค / because of + noun'), ('ขัดแย้ง', 'although + ประโยค / despite + noun'), ('ระหว่างประโยค', '. However, + ประโยค')],
   ex=[('The parts arrived, so we started production.', 'ชิ้นส่วนมาถึงแล้ว เราจึงเริ่มผลิต'), ('While the machine is running, do not open the door.', 'ขณะเครื่องทำงาน ห้ามเปิดประตู'),
       ('Despite the delay, we finished on time.', 'แม้จะล่าช้า เราก็เสร็จทันเวลา'), ('The test failed. Therefore, we checked the wiring.', 'การทดสอบไม่ผ่าน เราจึงตรวจการเดินสาย')],
   mis=[('Because of the machine was old, ...', 'Because the machine was old, ...', 'ตามด้วยประโยคใช้ because'),
        ('Although it was late, but we finished.', 'Although it was late, we finished.', 'ใช้ although กับ but ในประโยคเดียวกันไม่ได้'),
        ('The cost rose, however sales increased.', 'The cost rose. However, sales increased.', 'however เป็น adverb เชื่อมสองประโยคด้วย comma อย่างเดียวไม่ได้')],
   tip='ข้อสอบชอบให้เลือกระหว่าง because / because of, although / despite ดูว่าหลังช่องว่างเป็น "ประโยค" (มีกริยา) หรือ "คำนาม"',
   story=('The order was urgent, **so** we worked overtime. **Although** the team was tired, everyone stayed. **As a result**, we shipped on time.',
          'คำสั่งซื้อด่วน เราจึงทำงานล่วงเวลา แม้ทีมจะเหนื่อย ทุกคนก็อยู่ต่อ ผลคือเราส่งของได้ทันเวลา')),
  easy=('คำเชื่อมคือป้ายจราจรของประโยค: and ไปต่อ, but / however เลี้ยวกลับ, so / therefore ผลลัพธ์',
        ('It was late, <b>but</b> we finished. <b>Therefore</b>, ...', 'ช้า แต่เราก็เสร็จ ดังนั้น...'), 'หลังช่องเป็นประโยค = because / although · เป็นคำนาม = because of / despite')),

